/**
 * Per-game customization schema (MVP).
 *
 * A plain module (NO "use server") so it can be imported from server components,
 * "use server" action files AND the worker daemon alike — it holds no secrets and
 * performs no I/O.
 *
 * It declares, per game family, the available server *variants* (the loader/flavour
 * a player runs — Paper vs Vanilla, Carbon vs Oxide, …) and a versioned list of
 * *settings fields* that drive a dynamic UI. Fields are intentionally limited to
 * the handful of options players actually change, keyed on the game's own real
 * config keys (server.properties, PalWorldSettings.ini, cvars, …) — no invented
 * cvars — so a future real "apply" step can render them 1:1.
 *
 * Exports: `familyFor`, `schemaFor`, `validateConfig` plus the `GAME_CONFIG_SCHEMAS`
 * table and its types.
 */

/** Bump when the field set changes in a way the worker/apply step must notice. */
import { fieldRuleError, stringFieldError } from "./game-field-rules";
import { TERRARIA_KNOWN_VERSIONS, TERRARIA_PINNED_VERSION } from "./terraria-image";
import { versionLabel } from "./terraria-versions";
import { APPLIER_SPECS, applierFieldApply, appliersEnabled, type FieldApply } from "./game-config-appliers";
import { FIVEM_LICENSE_KEY_PATTERN, FIVEM_GAME_BUILDS, FIVEM_LOCALES, FIVEM_KNOWN_ARTIFACTS } from "./fivem";
import { BEDROCK_KNOWN_GOOD_VERSION, BEDROCK_LATEST_LABEL, BEDROCK_PREVIEW_LABEL } from "./bedrock-version";

export const GAME_CONFIG_VERSION = 1;

export type FieldType = "enum" | "bool" | "int" | "string";

/**
 * When a setting takes effect:
 *  - "deploy": needs a server restart / redeploy (world seed, tickrate, …)
 *  - "live":   can be pushed to a running server (motd, pvp, max players, …)
 * MVP treats both the same (simulated apply) but the UI surfaces the distinction.
 */
export type FieldPhase = "deploy" | "live";

export type ConfigField = {
  /** The game's own config key (e.g. "max-players", "ServerPlayerMaxNum"). */
  key: string;
  label: string;
  /** UI grouping heading. */
  group: string;
  type: FieldType;
  default: string | number | boolean;
  /** enum only — {value,label} choices. */
  options?: { value: string; label: string }[];
  /**
   * enum only. When true and `options` is long, the settings UI renders a
   * type-to-filter combobox (components/customer/SearchableSelect.tsx)
   * instead of a plain native `<select>` — a flat dropdown of 100+ entries
   * has no usable way to find one. Leave unset for short option lists
   * (gamemode, difficulty, …), where a native select is simpler and fine.
   */
  searchable?: boolean;
  /**
   * enum only. The live option list is fetched at render time (e.g. Terraria's /api/terraria-versions,
   * refreshed by a sweep), so `options` is only the built-in fallback and validation accepts any
   * dotted-number version; the worker applier refuses a version the platform does not actually have.
   */
  dynamicEnum?: boolean;
  /** int only — inclusive bounds. */
  min?: number;
  max?: number;
  phase: FieldPhase;
  /** optional one-line helper shown under the field. */
  help?: string;
  /**
   * string fields only. When true, `validateConfig` rejects a blank value —
   * used for values with no sane platform default where the server is
   * genuinely non-functional / unjoinable without a customer-supplied
   * credential (e.g. DST's Klei cluster TOKEN — an online DST cluster
   * refuses to start at all without one). Enforced both at order-creation
   * time (lib/game-order.ts, BEFORE payment) and at settings-save time
   * (lib/actions-game-config.ts), so it gates checkout AND blocks a customer
   * from blanking it back out later. See DST.TOKEN below for the motivating
   * incident (added same-day as the family, 2026-08-31 audit).
   */
  required?: boolean;
  /** string only: minimum length of a non-blank value (enforced by validateConfig + shown inline in the wizard). */
  minLength?: number;
  /** string only: value may not appear inside the value of this other field key (Valheim: password vs world name). */
  notInsideField?: string;
  /** string only: the deploy wizard pre-fills a random value the customer can change. */
  suggest?: "password";
  /**
   * Override the docker `-e KEY=` name that `applyGameConfigEnv`
   * (worker/game-variant.ts) substitutes into, when it differs from `key`.
   *
   * Found live 2026-09-11: Valheim's World Name field is keyed `"world"` (a
   * readable schema key, matches the game's own `-world` flag name) but the
   * lloesche/valheim-server image's actual env var is `WORLD_NAME`.
   * `applyGameConfigEnv` matches literally on `field.key`, so `-e world=`
   * never appeared in the setup script and the customer's chosen world name
   * was silently dropped at provisioning — every Valheim server booted on
   * the catalog's hardcoded default world regardless of what was ordered.
   * Set this whenever a field's readable schema key isn't the literal env
   * var name the image expects.
   */
  envKey?: string;
  /**
   * string fields only. Inclusive length bounds checked in addition to the
   * global 256-char cap (UI uses `maxLength` for the input's own limit).
   */
  maxLength?: number;
  /**
   * string fields only. Regex SOURCE (compiled with the `u` flag, tested
   * against the whole value) the value must match — data, not a function, so
   * the schema stays serialisable into the client settings form.
   */
  pattern?: string;
  /** Shown when `pattern`/length rules reject a value. */
  patternError?: string;
};

export { stringFieldError } from "./game-field-rules";

export type GameVariant = {
  id: string;
  label: string;
  description?: string;
  /**
   * Plain-language reason this type can't be picked for a NEW order or switched
   * to right now (the platform can't install it yet). An existing server that
   * already has it keeps it. Never set for something we merely haven't tested:
   * only for something we know does nothing.
   */
  unavailable?: string;
};

export type FamilySchema = {
  family: string;
  label: string;
  variants: GameVariant[];
  defaultVariant: string;
  fields: ConfigField[];
  /**
   * What a NEW order starts with when the customer (or an API caller) doesn't
   * choose. Separate from `defaultVariant` / `field.default` on purpose: those
  ],
};

const VALHEIM: FamilySchema = {
  family: "valheim",
  label: "Valheim",
  defaultVariant: "vanilla",
  variants: [
    { id: "vanilla", label: "Vanilla", description: "Standard dedicated server." },
    { id: "bepinex", label: "BepInEx", description: "BepInEx modding framework for Valheim mods." },
  ],
  // New Valheim orders start on BepInEx with crossplay on (2026-10-02, prd-003):
  // 2 of the 4 live servers were vanilla, so the mods their owners installed
  // could never load, and a console friend couldn't join until crossplay was
  // found in Settings. Existing servers are untouched (see FamilySchema.orderDefaults).
  // Crossplay default turned OFF (2026-10-06, owner): with -crossplay Valheim uses
  // PlayFab and never opens its game port, so PC players connecting by IP:port (what
  // the dashboard shows) can't join and the panel reports "not accepting connections".
  // Customers who need console/Xbox friends switch it on in Settings.
  orderDefaults: { variant: "bepinex", values: { CROSSPLAY: false } },
  // Valheim dedicated-server launch args + world modifiers.
  fields: [
    // Found live 2026-09-08: prisma/catalog.ts's valheim setupScript hardcodes
    // `-e SERVER_PASS='changeme12'` with no schema field for it at all — every
    // Valheim customer on the platform was silently sharing that ONE join
    // password, with no way to see or change it (a real customer ticket: "I
    // don't see the server password anywhere, can I change it?"). `required`
    // so checkout forces a real value in from day one, same precedent as
    // DST's TOKEN field above.
    {
      key: "SERVER_PASS",
      label: "Server password",
      group: "General",
      type: "string",
      default: "",
      phase: "deploy",
      required: true,
      minLength: 5,
      notInsideField: "world",
      suggest: "password",
      help: "Valheim requires a password of at least 5 characters (and it can't be part of the world name). We've suggested one — change it if you like; you can edit it later in Settings.",
    },
    // Added 2026-10-01 (customer Jay: console players find servers by NAME in the
    // in-game browser, and the name was hardcoded 'Nxeon' in prisma/catalog.ts's
    // setupScript, with no way to change it). Maps to lloesche/valheim-server's
    // SERVER_NAME env (`-name`). Default stays "Nxeon" = today's behaviour; the
    // apply path (worker/game-config.ts applyValheim) treats the untouched
    // default as "leave the running name alone", so saving other settings never
    // renames an existing server. Rules (Valheim itself publishes no hard limit;
    // these are conservative and shell-inert, the name travels through an
    // env-file and a quoted bash expansion): 3-64 characters; letters, digits,
    // spaces and  - _ . ' ! & ( ) [ ] + , # : ~ @ |  only; no leading/trailing
    // space; must not contain the server password (the game refuses to start
    // when it does; that cross-field rule is enforced in applyValheim).
    {
      key: "SERVER_NAME",
      label: "Server name",
      group: "General",
      type: "string",
      default: "Nxeon",
      phase: "deploy",
      minLength: 3,
      maxLength: 64,
      pattern: "^[\\p{L}\\p{N}][\\p{L}\\p{N} _.'!&()\\[\\]+,#:~@|-]*[\\p{L}\\p{N}.!)\\]]$",
      patternError:
        "Server name: use letters, numbers, spaces and - _ . ' ! & ( ) [ ] + , # : ~ @ | only, and start/end with a letter, number or . ! ) ].",
      help:
        "The name players see in the in-game server list (console players search by this). Leave as Nxeon to keep your current name. Must not contain your password.",
    },
    {
      key: "world",
      envKey: "WORLD_NAME",
      label: "World name",
      group: "World",
      type: "string",
      default: "Dedicated",
      phase: "deploy",
      help: "-world — the save file to load. A new name creates a fresh world.",
    },
    {
      key: "preset",
      label: "World modifier preset",
      group: "World",
      type: "enum",
      default: "normal",
      // applyValheim is always a full container recreate for any field change —
      // there is no live push mechanism at all (2026-09-10 audit).
      phase: "deploy",
      options: [
        { value: "normal", label: "Normal" },
        { value: "casual", label: "Casual" },
        { value: "easy", label: "Easy" },
        { value: "hard", label: "Hard" },
        { value: "hardcore", label: "Hardcore" },
        { value: "immersive", label: "Immersive" },
        { value: "hammer", label: "Hammer (creative)" },
      ],
      help: "-preset — global combat/resource modifiers.",
    },
    // Individual modifier overrides, distinct from the combined `preset`
    // above — Valheim itself lets these be tuned independently of whichever
    // preset is active. Values verified against the game's own known
    // -modifier value set (not guessed): deathpenalty accepts casual/
    // veryeasy/easy/normal/hard/hardcore, portals accepts casual/normal/
    // hard/veryhard. Requested directly by a customer 2026-09-09.
    {
      key: "deathpenalty",
      label: "Death penalty",
      group: "World",
      type: "enum",
      default: "normal",
      phase: "deploy",
      options: [
        { value: "casual", label: "Casual (keep everything)" },
        { value: "veryeasy", label: "Very easy" },
        { value: "easy", label: "Easy" },
        { value: "normal", label: "Normal" },
        { value: "hard", label: "Hard" },
        { value: "hardcore", label: "Hardcore (lose skills)" },
      ],
      help: "-modifier deathpenalty — what's lost on death.",
    },
    {
      key: "portals",
      label: "Portal restrictions",
      group: "World",
      type: "enum",
      default: "normal",
      phase: "deploy",
      options: [
        { value: "casual", label: "Casual (all metals allowed)" },
        { value: "normal", label: "Normal" },
        { value: "hard", label: "Hard" },
        { value: "veryhard", label: "Very hard (no portals)" },
      ],
      help: "-modifier portals — what can be sent through portals.",
    },
    // "normal" is this field's default/no-override choice, same convention as
    // deathpenalty/portals above — Valheim's own -modifier parser only accepts
    // none/muchless/less/more/muchmore for raids, not a literal "normal", so
    // that choice means "no override" and gets stripped rather than passed
    // (see applyValheim's own handling for exactly this reasoning). Requested
    // directly by a customer 2026-09-13.
    {
      key: "raids",
      label: "Raid frequency",
      group: "World",
      type: "enum",
      default: "normal",
      phase: "deploy",
      options: [
        { value: "none", label: "None (raids off)" },
        { value: "muchless", label: "Much less" },
        { value: "less", label: "Less" },
        { value: "normal", label: "Normal" },
        { value: "more", label: "More" },
        { value: "muchmore", label: "Much more" },
      ],
      help: "-modifier raids — how often random raid events occur.",
    },
    {
      key: "ADMINLIST_IDS",
      label: "Admin SteamIDs",
      group: "Access",
      type: "string",
      default: "",
      phase: "deploy",
      help: "Space-separated SteamID64s. Admins can kick/ban from the F5 console, and after typing devcommands can run server commands such as sleep and skiptime. god, fly and debugmode also need the Nxeon Dev Admin plugin on that admin's own PC (ask support).",
    },
    {
      key: "PERMITTEDLIST_IDS",
      label: "Whitelisted SteamIDs",
      group: "Access",
      type: "string",
      default: "",
      phase: "deploy",
      help: "Space-separated SteamID64s. Blank = anyone with the server password may join.",
    },
    {
      key: "CROSSPLAY",
      label: "Crossplay",
      group: "General",
      type: "bool",
      default: false,
      phase: "deploy",
      help: "Lets non-Steam (Xbox/PS/Game Pass) clients join.",
    },
    {
      key: "BACKUPS_MAX_AGE",
      label: "Keep backups for (days)",
      group: "World",
      type: "int",
      default: 3,
      min: 1,
      max: 30,
      phase: "deploy",
      help: "The image already backs up your world on a schedule — this controls how long backups are kept.",
    },
  ],
};

  if (desiredRaw == null) return { set: null };
  const desired = String(desiredRaw).trim();
  if (desired.length === 0 || desired === VALHEIM_DEFAULT_SERVER_NAME) return { set: null };
  if (current === desired) return { set: null };
  const field = schemaFor("valheim")?.fields.find((f) => f.key === "SERVER_NAME");
  const bad = field ? stringFieldError(field, desired) : "invalid";
  if (bad) return { set: null, note: `Ignored the server name: ${bad}` };
  if (password.length >= 5 && desired.toLowerCase().includes(password.toLowerCase())) {
    return { set: null, note: "Ignored the server name: Valheim won't start if the server name contains the password." };
  }
  return { set: desired };
}

async function applyValheim(conn: Client, sftp: SFTPWrapper, v: Values, gameVariant: string): Promise<ApplyOutcome> {
  const envMap = await readContainerEnv(conn, VALHEIM_CONTAINER);
  if (!envMap) {
    return { ok: false, applied: [], notes: [`Could not find the "${VALHEIM_CONTAINER}" container — nothing was changed.`] };
  }

  const applied: string[] = [];
  const notes: string[] = [];

  // BepInEx variant switch — found live 2026-09-09: `Server.gameVariant`
  // (lib/game-config.ts's vanilla/bepinex choice) was never applied for any
  // family post-provision, ANYWHERE in this codebase — worker/game-variant.ts's
  // applyGameVariant is provision-time-only and Minecraft-only, and
  // gameConfigApply resolves `variant` but never threads it into a family's
  // real-apply function. So picking "BepInEx" in Settings on an already-running
  // Valheim server did nothing at all. lloesche/valheim-server has this built
  // in already (`-e BEPINEX=true`, verified against its own README): it
  // downloads BepInExPack Valheim from Thunderstore, creates
  // /config/bepinex/plugins for user-added mods, and copies them into the
  // real plugin dir on boot — no custom bootstrap needed here, just wiring
  // the flag through. Diff-guarded like SERVER_PASS above: only recreate when
  // the setting genuinely differs from what's running.
  const wantsBepinex = gameVariant === "bepinex";
  const currentBepinex = envMap.get("BEPINEX") === "true";
  if (wantsBepinex !== currentBepinex) {
    envMap.set("BEPINEX", wantsBepinex ? "true" : "false");
    applied.push(wantsBepinex ? "bepinex-enabled" : "bepinex-disabled");
  }

  // CROSSPLAY — found live 2026-09-15 via a real customer ticket (a PS5
  // player couldn't join): lib/game-config.ts's CROSSPLAY field has existed
  // since this schema shipped and lets a customer flip it on in Settings, but
  // nothing here ever applied it to the real container — same class of bug
  // as BEPINEX above (a schema field with no real-apply wiring). Confirmed
  // live: this customer's gameConfig said CROSSPLAY: true, but `docker
  // inspect` showed no CROSSPLAY env var on the actual running container at
  // all. lloesche/valheim-server's own docs: `-e CROSSPLAY=true` switches
  // Steam matchmaking to PlayFab so Xbox/PlayStation/Microsoft Store clients
  // can join. Same diff-guard shape as BEPINEX — only recreate when it
  // genuinely differs from what's running.
  if (v["CROSSPLAY"] != null) {
    const wantsCrossplay = bool(v["CROSSPLAY"]) === "true";
    const currentCrossplay = envMap.get("CROSSPLAY") === "true";
    if (wantsCrossplay !== currentCrossplay) {
      envMap.set("CROSSPLAY", wantsCrossplay ? "true" : "false");
      applied.push(wantsCrossplay ? "crossplay-enabled" : "crossplay-disabled");
    }
  }

  // Diff-guarded like SERVER_PASS below — found live 2026-09-11 via a real
  // customer's data-loss incident: this used to set WORLD_NAME unconditionally
  // on every Settings save, since the form always resends every field (its
  // `world` value comes from the STORED gameConfig, which may not match what's
  // actually running — e.g. the provisioning-time envKey fix above was applied
  // after this customer's server, or an earlier save already switched it).
  // Saving one unrelated field (their death penalty) silently switched their
  // live world to that stored value, starting a brand-new empty world and
  // orphaning their real one. Only recreate for `world` when it genuinely
  // differs from what the container is CURRENTLY running.
  const desiredWorld = v["world"] != null ? String(v["world"]).trim() : "";
  if (desiredWorld.length > 0 && envMap.get("WORLD_NAME") !== desiredWorld) {
    envMap.set("WORLD_NAME", desiredWorld);
    applied.push("world");
  }
  // SERVER_NAME (added 2026-10-01): the name in the in-game server list.
  // Existing servers must not change behaviour, and Settings resends every
  // field with its default on every save, so the untouched default is treated
  // as "leave the running name alone" (a staff-renamed server is not reverted
  // by an unrelated save). Only a different, valid, changed name recreates the
  // container. Valheim refuses to start when the password appears inside the
  // name, so that combination is rejected here (cross-field rule).
  const nameChange = planValheimServerName(v["SERVER_NAME"], envMap.get("SERVER_NAME"), String(v["SERVER_PASS"] ?? envMap.get("SERVER_PASS") ?? ""));
  if (nameChange.note) notes.push(nameChange.note);
  if (nameChange.set) {
    envMap.set("SERVER_NAME", nameChange.set);
    applied.push("server-name");
  }
  if (v["preset"] != null) {
    const preset = String(v["preset"]);
    if (!VALHEIM_PRESETS.has(preset)) {
      notes.push(`Ignored an unrecognised world preset "${preset}".`);
    } else {
      const args = envMap.get("SERVER_ARGS") ?? "";
      envMap.set("SERVER_ARGS", upsertArg(args, "-preset", preset));
      applied.push("preset");
    }
  }
  // Individual modifier overrides — same shape as `preset` above, just a
  // two-token flag (`-modifier <name> <value>`); upsertArg's literal-match
  // already handles a multi-word flag string correctly.
  for (const [key, modifierName, valid] of [
    ["deathpenalty", "deathpenalty", VALHEIM_DEATHPENALTY_VALUES] as const,
    ["portals", "portals", VALHEIM_PORTALS_VALUES] as const,
    ["raids", "raids", VALHEIM_RAIDS_VALUES] as const,
  ]) {
    if (v[key] == null) continue;
    const value = String(v[key]);
    if (!valid.has(value)) {
      notes.push(`Ignored an unrecognised ${key} value "${value}".`);
      continue;
    }
    const args = envMap.get("SERVER_ARGS") ?? "";
    // "normal" is this field's default/no-override choice in our own
    // dropdown, but Valheim's own -modifier parser doesn't accept "normal"
    // as an explicit value at all — found live 2026-09-09 via a real
    // customer's BepInEx log: "Could not parse 'deathpenalty' with a value
    // of 'normal' as a world modifier" (same for portals). The active
    // -preset already sets both to their default when no override is
    // present, so "Normal" here means "no override," not "pass the literal
    // word" — strip the flag instead of setting it to a value the game
    // itself rejects.
    envMap.set("SERVER_ARGS", value === "normal" ? removeArg(args, `-modifier ${modifierName}`) : upsertArg(args, `-modifier ${modifierName}`, value));
    applied.push(key);
  }
  // SERVER_PASS: found live 2026-09-08 — every Valheim server shared the
  // catalog's hardcoded 'changeme12' join password (prisma/catalog.ts) with
  // no schema field to change it (lib/game-config.ts's new SERVER_PASS
  // field). Only diff-guard on the actual env value, not "was it provided" —
  // Settings always resends every field on save, so an unconditional set
  // would recreate the container (a real player-facing restart) on every
  // unrelated settings change too.
  if (v["SERVER_PASS"] != null) {
    const desired = String(v["SERVER_PASS"]);
    if (desired.trim().length > 0 && envMap.get("SERVER_PASS") !== desired) {
      envMap.set("SERVER_PASS", desired);
      applied.push("password");
    }
  }
  // Self-healing, not just a one-shot side effect of toggling BepInEx on:
  // a customer already on the bepinex variant (from before this feature
  // shipped, or any earlier recreate that predates it) would otherwise never
  // pick up the plugin mount, since nothing else about their settings changed
  // to avoid the early-return below. Check the LIVE container's own mounts
  // (not just our env-map diff) so this repairs itself the next time
  // settings are saved for any reason, same pattern as Minecraft's
  // stale-image self-heal.
  let devAdminMountMissing = false;
  if (wantsBepinex) {
    const mounts = await execRemote(conn, `docker inspect ${VALHEIM_CONTAINER} --format '{{json .Mounts}}' 2>/dev/null`);
    devAdminMountMissing = mounts.code !== 0 || !mounts.stdout.includes(VALHEIM_DEVADMIN_VM_DIR);
    if (devAdminMountMissing) applied.push("devcommands-fix-deployed");
  }

  if (applied.length === 0) {
    return { ok: true, applied: [], notes: notes.length ? notes : ["No changes to apply."] };
  }

  await writeEnvFile(conn, sftp, "/root/valheim.env", envMap);

  if (wantsBepinex) {
    try {
      await execRemote(conn, `mkdir -p ${VALHEIM_DEVADMIN_VM_DIR}`);
      await sftpWriteBinary(sftp, VALHEIM_DEVADMIN_VM_PATH, readFileSync(VALHEIM_DEVADMIN_DLL_LOCAL));
    } catch (e) {
      // Never block the rest of the settings apply over this — worst case the
      // customer's server comes up BepInEx-enabled without our plugin, same
      // as before this feature existed.
      notes.push(`Could not deploy the built-in devcommands fix: ${String(e instanceof Error ? e.message : e).slice(0, 160)}`);
    }
  }

  const res = await recreateGameContainer(conn, {
    family: "valheim",
    container: VALHEIM_CONTAINER,
    runFlags: valheimRunFlags(wantsBepinex),
    image: VALHEIM_IMAGE,
  });
  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };

  if (applied.includes("world")) {
    notes.push("A new world name starts a fresh world — your previous world is still saved and comes back if you set the old name again.");
  }
  if (applied.includes("bepinex-enabled")) {
    notes.push(
      "BepInEx is installing now (a one-time download, can take a few minutes on first boot). " +
        "Drop other plugin files into your server's /opt/valheim/config/bepinex/plugins folder via File Manager to install more mods."
    );
  }
  // No customer note for "devcommands-fix-deployed": the server copy of
  // NxeonDevAdmin unlocks nothing by itself (it is a client-side plugin), so
  // we no longer tell customers that admins "can now use devcommands".
  notes.push("Your server restarted to apply these — players can rejoin once it finishes loading.");

  return { ok: true, applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`], notes };
}

// ---------------------------------------------------------------------------
// CS2: the inline server.cfg writer that lived here was retired 2026-10-02. joedwards32/cs2 regenerates
// server.cfg from its own template on EVERY boot, so those writes never survived a restart. CS2 now goes through
// the applier registry (worker/game-config-appliers/cs2.ts: container env, the image's real mechanism).
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Palworld → container recreation with an --env-file (NOT direct ini editing)
//
// Found live 2026-09-05 (customer ticket: their hand-edits to
// PalWorldSettings.ini kept reverting): the `thijsvanloef/palworld-server-docker`
// image's `start.sh` unconditionally regenerates PalWorldSettings.ini from its
