"use client";

import { useState, useTransition } from "react";
import type { ConsoleJoin } from "@/lib/console-join";
import { consoleJoinText, parseValheimJoinCode } from "@/lib/console-join";
import { getGameLogs } from "@/lib/actions-game-control";

/**
 * Body of the "Console players" card (growth item prd-015). The instructions are
 * generated server-side from this server's real settings (lib/console-join.ts)
 * and passed in; this only renders them, copies them, and — for Valheim — looks
 * the join code up in the server's own log on request.
 */
export function GameConsoleJoin({
  serverId, info, running, onNavigate,
}: {
  serverId: string; info: ConsoleJoin; running: boolean; onNavigate?: (tab: string) => void;
}) {
  const [copied, setCopied] = useState(false);
  const [code, setCode] = useState<string | null>(null);
  const [codeMsg, setCodeMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const copy = () => {
    navigator.clipboard?.writeText(consoleJoinText(info)).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1800); }, () => {});
  };
  const findCode = () => start(async () => {
    setCodeMsg(null); setCode(null);
    const r = await getGameLogs(serverId).catch(() => null);
    if (!r || !r.ok) { setCodeMsg(r && !r.ok ? r.error : "Could not read the server log."); return; }
    const c = parseValheimJoinCode(r.lines);
    if (c) setCode(c);
    else setCodeMsg("No join code in the recent log. Restart the server, wait a minute, and try again.");
  });

  return (
    <div className="flex flex-col gap-3">
      <p className={"rounded-[10px] border px-3 py-2 text-[12.5px] leading-relaxed " + (info.status === "ready" ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-200" : "border-amber-500/35 bg-amber-500/10 text-amber-200")}>
        {info.headline}
        {info.fix && (
          <>
            {" "}<b>{info.fix.label}</b> ({info.fix.where}).{" "}
            {onNavigate && <button type="button" onClick={() => onNavigate("settings")} className="font-semibold underline">Open Settings</button>}
          </>
        )}
      </p>
      <p className="text-[11.5px] text-tx-faint">For {info.platforms.join(", ")}</p>
      <ol className="flex flex-col gap-2">
        {info.steps.map((s, i) => (
          <li key={i} className="flex gap-2.5 text-[12.5px] leading-relaxed text-tx-dim">
            <span className="grid h-5 w-5 flex-none place-items-center rounded-full bg-[#7b3fef]/30 text-[10.5px] font-bold text-white">{i + 1}</span>
            <span className="min-w-0">{s}</span>
          </li>
        ))}
      </ol>
      {info.joinCodeFromLog && (
        <div className="flex flex-wrap items-center gap-2">
          <button type="button" disabled={pending || !running} onClick={findCode}
            className="rounded-[9px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-white transition hover:border-brand-400/45 disabled:opacity-40">
            {pending ? "Looking…" : "Find the join code"}
          </button>
          {!running && <span className="text-[11.5px] text-tx-faint">Start the server first.</span>}
          {code && <code className="rounded-[8px] border border-rim-hi bg-[rgba(4,6,16,.7)] px-2.5 py-1 font-mono text-[13px] font-bold text-white">{code}</code>}
          {codeMsg && <span className="text-[11.5px] text-amber-300">{codeMsg}</span>}
        </div>
      )}
      <ul className="flex flex-col gap-1">
        {info.notes.map((n, i) => <li key={i} className="text-[11.5px] leading-relaxed text-tx-faint">{n}</li>)}
      </ul>
      <button type="button" onClick={copy} className="w-fit rounded-[9px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white">
        {copied ? "Copied" : "Copy these steps to share with friends"}
      </button>
    </div>
  );
}
