/**
 * Valheim crossplay health, auto-heal decisions, memory watch and the
 * "no daily restart" container defaults. PURE (no I/O): the worker sweep
 * (worker/valheim-watch.ts) feeds it journal lines and readings, persists what
 * it returns on the ValheimWatch row, and acts on its decisions. The panel and
 * the rollout script read the same row / call the same functions.
 *
 * Why this exists (real incident 2026-10-07, TERRAHEIM, crossplay + BepInEx):
 * the lloesche/valheim-server image's own default RESTART_CRON ("10 5 * * *")
 * restarted the game at 05:10 UTC. Shutdown logged "Failed to send, suspend TX
 * on playfab/..." (the old PlayFab lobby was probably never cleaned up), the
 * boot then logged `Session "Nxeon" registered with join code 187714` followed
 * by an exception in `ZPlayFabMatchmaking.OnCheckJoinCodeSuccess`, and never
 * the healthy `Session "<name>" with join code <code> and IP <ip>:<port> is
 * active with N player(s)` line. Nobody could join for ~45 minutes; a plain
 * container restart fixed it.
 *
 * So, per server:
 *   healthy   = an "is active with" line after the latest start
 *   broken    = the OnCheckJoinCodeSuccess/PlayFab exception after a start, or
 *               no "is active" line within CROSSPLAY_START_WINDOW_MS of a start,
 *               or repeated "PlayFab ... network error" with 0 players for
 *               CROSSPLAY_NETERR_WINDOW_MS
 *   on broken: restart ONCE (GAME_POWER, audited), recheck; still broken after
 *              that restart -> admin alert, no more restarts until it is
 *              healthy again. Never more than HEAL_MAX_PER_DAY restarts a day.
 */

// ---------------------------------------------------------------------------
// Container defaults (layer 1: no daily restart; layer 3: clean shutdown)
// ---------------------------------------------------------------------------

/**
 * The image reads `RESTART_CRON=${RESTART_CRON-10 5 * * *}` (note `-`, not
 * `:-`): an env var that is SET but EMPTY disables the cron entirely (its
 * bootstrap logs "Environment variable RESTART_CRON is empty - no automatic
 * valheim-server restart scheduled"). Unset = the daily 05:10 restart.
 * Update-triggered restarts are a different mechanism (UPDATE_CRON +
 * UPDATE_IF_IDLE, the updater restarts only when an update exists and the
 * server is idle) and are deliberately left alone.
 */
export const VALHEIM_RESTART_CRON_ENV = "RESTART_CRON";
export const VALHEIM_RESTART_CRON_OFF = "";

/**
 * Seconds docker / systemd give the container to stop. Inside the image,
 * valheim-server's own shutdown() sends SIGINT, waits 29 s, then SIGTERM, then
 * another 29 s, then SIGKILL; supervisord's stopwaitsecs for it is 90. The
 * generated unit used `docker stop -t 30`, i.e. SIGKILL after 30 s, which can
 * land before the game finishes saving and unregistering its PlayFab lobby.
 * 120 s is what the image's own README uses (`--stop-timeout 120`).
 */
export const VALHEIM_STOP_TIMEOUT_S = 120;

/**
 * Rewrite a Valheim setupScript (`docker run -d --name valheim ...`) so the
 * container is created with the daily restart disabled and the long stop
 * timeout. Idempotent; other families and unexpected shapes are returned
 * unchanged.
 */
export function applyValheimContainerDefaults(setupScript: string, family: string | null): string {
  if (family !== "valheim") return setupScript;
  const m = /(docker run\s+(?:-d|--detach)\b.*?--name[= ]"?valheim"?)(\s)/.exec(setupScript);
  if (!m) return setupScript;
  const add: string[] = [];
  if (!/-e\s+RESTART_CRON=/.test(setupScript)) add.push(`-e ${VALHEIM_RESTART_CRON_ENV}=`);
  if (!/--stop-timeout[= ]\d+/.test(setupScript)) add.push(`--stop-timeout ${VALHEIM_STOP_TIMEOUT_S}`);
  if (add.length === 0) return setupScript;
  return setupScript.replace(m[0], `${m[1]} ${add.join(" ")}${m[2]}`);
}

/** What a live container env needs changed so the image never restarts on a schedule. */
export function planValheimRestartCron(env: Map<string, string> | Record<string, string | undefined>): { change: boolean; current: string | null } {
  const cur = env instanceof Map ? env.get(VALHEIM_RESTART_CRON_ENV) : env[VALHEIM_RESTART_CRON_ENV];
  const current = cur === undefined ? null : cur;
  return { change: current !== VALHEIM_RESTART_CRON_OFF, current };
}

/** Human description of the image's effective restart schedule for a given env value. */
export function describeImageRestart(current: string | null): string {
  if (current === null) return "image default: daily at 05:10 (container time zone, UTC) when idle";
  if (current.trim() === "") return "off";
  return `cron "${current}"`;
}

// ---------------------------------------------------------------------------
// Log parsing (layer 2 + 4)
// ---------------------------------------------------------------------------

/** One journal line from `journalctl -o short-unix`: "<epoch.usec> <host> <ident>[pid]: <msg>". */
export type JournalLine = { ts: number; text: string };

export function parseJournalShortUnix(stdout: string): JournalLine[] {
  const out: JournalLine[] = [];
  for (const raw of stdout.split(/\r?\n/)) {
    const m = /^(\d{9,11}(?:\.\d+)?)\s+(.*)$/.exec(raw);
    if (!m) continue;
    const ts = Number(m[1]) * 1000;
    if (!Number.isFinite(ts)) continue;
    out.push({ ts, text: m[2] });
  }
  return out;
}

export type ValheimEvent =
  | { kind: "start"; ts: number }
  | { kind: "shutdown"; ts: number }
  | { kind: "registered"; ts: number; code: string; name: string | null }
  | { kind: "active"; ts: number; code: string; addr: string | null; players: number }
  | { kind: "joincode_error"; ts: number }
  | { kind: "net_error"; ts: number }
  | { kind: "players"; ts: number; players: number };

// Patterns, verified against a real lloesche/valheim-server crossplay guest
// (see test/valheim-health.test.ts for the literal lines). "start" is the
// image's own `info "Running Valheim Server"` emitted right before it execs
// the game binary (valheim-server run_server), so it marks every game start:
// a container start, a supervisorctl restart and an update restart alike.
const RE_START = /Running Valheim Server\b/;
const RE_SHUTDOWN = /Shutting down Valheim server with PID|Shutdown complete\b/;
const RE_REGISTERED = /Session "([^"]*)" registered with join code (\d{4,10})/;
const RE_ACTIVE = /Session "([^"]*)" with join code (\d{4,10}) and IP (\S+?) is active with (\d+) player\(s\)/;
const RE_JOINCODE_ERR = /ZPlayFabMatchmaking\.OnCheckJoinCodeSuccess/;
const RE_NET_ERR = /PlayFab[^\n]{0,80}network error|network error[^\n]{0,80}PlayFab/i;
const RE_PLAYERS = /now (\d+) player\(s\)/i;

export function parseValheimEvents(lines: JournalLine[]): ValheimEvent[] {
  const ev: ValheimEvent[] = [];
  for (const { ts, text } of lines) {
    let m: RegExpExecArray | null;
    if (RE_START.test(text)) { ev.push({ kind: "start", ts }); continue; }
    if ((m = RE_ACTIVE.exec(text))) { ev.push({ kind: "active", ts, code: m[2], addr: m[3] || null, players: Number(m[4]) }); continue; }
    if ((m = RE_REGISTERED.exec(text))) { ev.push({ kind: "registered", ts, code: m[2], name: m[1] || null }); continue; }
    if (RE_JOINCODE_ERR.test(text)) { ev.push({ kind: "joincode_error", ts }); continue; }
    if (RE_NET_ERR.test(text)) { ev.push({ kind: "net_error", ts }); continue; }
    if (RE_SHUTDOWN.test(text)) { ev.push({ kind: "shutdown", ts }); continue; }
    if ((m = RE_PLAYERS.exec(text))) { ev.push({ kind: "players", ts, players: Number(m[1]) }); continue; }
  }
  return ev;
}

// ---------------------------------------------------------------------------
// Crossplay state (layer 2)
// ---------------------------------------------------------------------------

export const CROSSPLAY_START_WINDOW_MS = 4 * 60_000;
export const CROSSPLAY_NETERR_MIN_COUNT = 3;
export const CROSSPLAY_NETERR_WINDOW_MS = 10 * 60_000;
/** After an auto-heal restart, how long to wait for a fresh start marker before calling the heal failed. */
export const HEAL_RESTART_GRACE_MS = 10 * 60_000;
export const HEAL_MAX_PER_DAY = 3;

/** What the sweep remembers between runs (a subset of the ValheimWatch row). */
export type CrossplayMemory = {
  lastStartAt: Date | null;
  lastShutdownAt: Date | null;
  lastActiveAt: Date | null;
  lastRegisteredAt: Date | null;
  lastJoinCodeErrorAt: Date | null;
  joinCode: string | null;
  sessionAddr: string | null;
  players: number | null;
  netErrorFirstAt: Date | null;
  netErrorLastAt: Date | null;
  netErrorCount: number;
};

export const EMPTY_MEMORY: CrossplayMemory = {
  lastStartAt: null, lastShutdownAt: null, lastActiveAt: null, lastRegisteredAt: null, lastJoinCodeErrorAt: null,
  joinCode: null, sessionAddr: null, players: null, netErrorFirstAt: null, netErrorLastAt: null, netErrorCount: 0,
};

/** Fold newly read events into the remembered facts. Pure. */
export function foldEvents(prev: CrossplayMemory, events: ValheimEvent[]): CrossplayMemory {
  const m: CrossplayMemory = { ...prev };
  for (const e of events) {
    const at = new Date(e.ts);
    switch (e.kind) {
      case "start":
        m.lastStartAt = at;
        // A new process: its own lobby, its own code, nobody connected yet.
        m.joinCode = null; m.sessionAddr = null; m.players = 0;
        m.netErrorFirstAt = null; m.netErrorLastAt = null; m.netErrorCount = 0;
        break;
      case "shutdown":
        m.lastShutdownAt = at;
        break;
      case "registered":
        m.lastRegisteredAt = at;
        m.joinCode = e.code;
        break;
      case "active":
        m.lastActiveAt = at;
        m.joinCode = e.code;
        m.sessionAddr = e.addr;
        m.players = e.players;
        // A healthy session line ends any network-error spell.
        m.netErrorFirstAt = null; m.netErrorLastAt = null; m.netErrorCount = 0;
        break;
      case "joincode_error":
        m.lastJoinCodeErrorAt = at;
        break;
      case "net_error":
        if (!m.netErrorFirstAt) m.netErrorFirstAt = at;
        m.netErrorLastAt = at;
        m.netErrorCount += 1;
        break;
      case "players":
        m.players = e.players;
        break;
    }
  }
  return m;
}

export type CrossplayState = "off" | "unknown" | "starting" | "healthy" | "reconnecting" | "broken" | "stopped";

const after = (a: Date | null, b: Date | null) => !!a && (!b || a.getTime() > b.getTime());
const atOrAfter = (a: Date | null, b: Date | null) => !!a && (!b || a.getTime() >= b.getTime());

/**
 * Classify the crossplay session. `running` = the game container is running
 * right now (from docker inspect), `crossplay` = the LIVE container env has
 * CROSSPLAY=true (not just the saved setting).
 */
export function classifyCrossplay(i: { crossplay: boolean; running: boolean; mem: CrossplayMemory; now: Date }): { state: CrossplayState; reason: string } {
  const { mem, now } = i;
  if (!i.crossplay) return { state: "off", reason: "Crossplay is off for this server." };
  if (!i.running) return { state: "stopped", reason: "The game is not running." };
  // A shutdown after the latest start with no new start = mid-restart.
  if (after(mem.lastShutdownAt, mem.lastStartAt) && mem.lastStartAt) return { state: "starting", reason: "Restarting." };

  const errAfterStart = after(mem.lastJoinCodeErrorAt, mem.lastStartAt) && !atOrAfter(mem.lastActiveAt, mem.lastJoinCodeErrorAt);
  if (errAfterStart) {
    return { state: "broken", reason: "Crossplay registration failed after the last start (PlayFab join-code check threw an exception)." };
  }

  const activeAfterStart = mem.lastActiveAt && atOrAfter(mem.lastActiveAt, mem.lastStartAt);
  if (activeAfterStart) {
    if (mem.netErrorFirstAt && mem.netErrorCount > 0 && after(mem.netErrorFirstAt, mem.lastActiveAt)) {
      const spell = now.getTime() - mem.netErrorFirstAt.getTime();
      if (mem.netErrorCount >= CROSSPLAY_NETERR_MIN_COUNT && (mem.players ?? 0) === 0 && spell >= CROSSPLAY_NETERR_WINDOW_MS) {
        return { state: "broken", reason: `Repeated PlayFab network errors for ${Math.round(spell / 60_000)} min with nobody connected.` };
      }
      return { state: "reconnecting", reason: "PlayFab reported network errors; waiting to see if it recovers." };
    }
    return { state: "healthy", reason: "The crossplay session is registered and active." };
  }

  if (!mem.lastStartAt) {
    // Nothing seen since we started watching: neither a start nor an active line.
    return { state: "unknown", reason: "Waiting for the server to report its crossplay session." };
  }
  const since = now.getTime() - mem.lastStartAt.getTime();
  if (since < CROSSPLAY_START_WINDOW_MS) return { state: "starting", reason: "The server is starting and registering its crossplay session." };
  return { state: "broken", reason: `No active crossplay session ${Math.round(since / 60_000)} min after the last start.` };
}

// ---------------------------------------------------------------------------
// Auto-heal decision (layer 2)
// ---------------------------------------------------------------------------

export type HealMemory = {
  /** When the current broken spell's auto-restart was queued (null = none this spell). */
  healQueuedAt: Date | null;
  /** When admins were alerted for the current spell (null = not yet). */
  alertedAt: Date | null;
  /** Recent auto-heal restarts (any spell), newest last; trimmed to 24 h by the caller. */
  healHistory: Date[];
};

export type HealDecision =
  | { action: "none"; why: string; clearSpell?: boolean }
  | { action: "restart"; why: string }
  | { action: "alert"; why: string };

/**
 * One decision per sweep. Never loops: one restart per broken spell, a daily
 * cap, and nothing while players are connected, a job is in flight, or
 * auto-heal is switched off. "Still broken after the heal" means a fresh start
 * after the heal that then classified broken, or no fresh start at all within
 * HEAL_RESTART_GRACE_MS.
 */
export function decideHeal(i: {
  state: CrossplayState;
  mem: CrossplayMemory;
  heal: HealMemory;
  now: Date;
  jobInFlight: boolean;
  autoHealEnabled: boolean;
}): HealDecision {
  const { state, mem, heal, now } = i;
  if (state === "healthy" || state === "off" || state === "stopped") {
    return heal.healQueuedAt || heal.alertedAt ? { action: "none", why: "recovered", clearSpell: true } : { action: "none", why: state };
  }
  if (i.jobInFlight) return { action: "none", why: "a job is already running for this server" };

  if (heal.healQueuedAt) {
    const restartedSinceHeal = after(mem.lastStartAt, heal.healQueuedAt);
    if (state === "broken" && restartedSinceHeal) {
      return heal.alertedAt ? { action: "none", why: "already alerted" } : { action: "alert", why: "still broken after the automatic restart" };
    }
    if (!restartedSinceHeal && now.getTime() - heal.healQueuedAt.getTime() > HEAL_RESTART_GRACE_MS) {
      return heal.alertedAt ? { action: "none", why: "already alerted" } : { action: "alert", why: "the automatic restart did not produce a fresh start" };
    }
    return { action: "none", why: "waiting for the automatic restart to finish" };
  }

  if (state !== "broken") return { action: "none", why: state };
  if ((mem.players ?? 0) > 0) return { action: "none", why: "players are connected; not restarting" };
  const dayAgo = now.getTime() - 24 * 60 * 60_000;
  const recent = heal.healHistory.filter((d) => d.getTime() > dayAgo).length;
  if (recent >= HEAL_MAX_PER_DAY) {
    return heal.alertedAt ? { action: "none", why: "daily auto-restart cap reached" } : { action: "alert", why: `broken, and the daily cap of ${HEAL_MAX_PER_DAY} automatic restarts is used up` };
  }
  if (!i.autoHealEnabled) {
    return heal.alertedAt ? { action: "none", why: "auto-heal is off" } : { action: "alert", why: "broken (auto-heal is switched off, alert only)" };
  }
  return { action: "restart", why: "crossplay broken" };
}

// ---------------------------------------------------------------------------
// Panel view (layer 4)
// ---------------------------------------------------------------------------

export type CrossplayBadge = "healthy" | "reconnecting" | "attention" | "checking" | "off";

export function crossplayBadge(state: string | null | undefined): { badge: CrossplayBadge; label: string } {
  switch (state) {
    case "healthy": return { badge: "healthy", label: "Crossplay healthy" };
    case "starting":
    case "reconnecting": return { badge: "reconnecting", label: "Reconnecting" };
    case "broken": return { badge: "attention", label: "Needs attention" };
    case "off": return { badge: "off", label: "Crossplay off" };
    case "stopped": return { badge: "off", label: "Server stopped" };
    default: return { badge: "checking", label: "Checking" };
  }
}

/** "players join with code X, or by IP host:port". Null pieces are left out, never guessed. */
export function joinInstructions(i: { joinCode: string | null; connect: string | null }): string {
  const parts: string[] = [];
  if (i.joinCode) parts.push(`with code ${i.joinCode}`);
  if (i.connect) parts.push(`by IP ${i.connect}`);
  if (parts.length === 0) return "The join code appears here once the server has registered its crossplay session.";
  return `Players join ${parts.join(", or ")}.`;
}

// ---------------------------------------------------------------------------
// Memory watch (layer 5)
// ---------------------------------------------------------------------------

/** Parse MemTotal / MemAvailable (kB) from /proc/meminfo text. */
export function parseMeminfo(text: string): { totalMb: number; availMb: number } | null {
  const t = /^MemTotal:\s+(\d+)\s*kB/m.exec(text);
  const a = /^MemAvailable:\s+(\d+)\s*kB/m.exec(text);
  if (!t || !a) return null;
  return { totalMb: Math.round(Number(t[1]) / 1024), availMb: Math.round(Number(a[1]) / 1024) };
}

/** Low = under max(MEM_LOW_FLOOR_MB, MEM_LOW_FRACTION of RAM). */
export const MEM_LOW_FLOOR_MB = 300;
export const MEM_LOW_FRACTION = 0.08;
export const MEM_LOW_SUSTAIN_MS = 15 * 60_000;

export function memLowThresholdMb(totalMb: number): number {
  return Math.max(MEM_LOW_FLOOR_MB, Math.round(totalMb * MEM_LOW_FRACTION));
}

/**
 * Track a low-memory spell. Returns the new `lowSince`, whether the customer
 * hint should show, and whether this sample STARTS the hint (log it once).
 * Recovery needs 25% headroom over the threshold so a value hovering at the
 * line does not flap the hint.
 */
export function memoryDecision(i: { totalMb: number; availMb: number; lowSince: Date | null; hintSince: Date | null; now: Date }): {
  lowSince: Date | null; hint: boolean; hintStarted: boolean; thresholdMb: number;
} {
  const thr = memLowThresholdMb(i.totalMb);
  if (i.availMb < thr) {
    const lowSince = i.lowSince ?? i.now;
    const sustained = i.now.getTime() - lowSince.getTime() >= MEM_LOW_SUSTAIN_MS;
    return { lowSince, hint: sustained || !!i.hintSince, hintStarted: sustained && !i.hintSince, thresholdMb: thr };
  }
  if (i.hintSince && i.availMb < thr * 1.25) return { lowSince: i.lowSince, hint: true, hintStarted: false, thresholdMb: thr };
  return { lowSince: null, hint: false, hintStarted: false, thresholdMb: thr };
}

// ---------------------------------------------------------------------------
// Scheduled restart in the server's region time (layer 1, optional setting)
// ---------------------------------------------------------------------------

function tzOffsetMs(at: Date, tz: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: tz, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit",
  }).formatToParts(at);
  const g = (t: string) => Number(parts.find((p) => p.type === t)?.value ?? 0);
  const asUtc = Date.UTC(g("year"), g("month") - 1, g("day"), g("hour") % 24, g("minute"), g("second"));
  return asUtc - Math.floor(at.getTime() / 1000) * 1000;
}

function validTz(tz: string | null | undefined): string {
  if (!tz) return "UTC";
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return tz;
  } catch {
    return "UTC";
  }
}

/**
 * Next instant strictly after `from` when the wall clock in `tz` reads
 * hour:minute. DST-safe: a local time that does not exist that day (spring
 * forward) lands on the first valid instant after it.
 */
export function computeNextRunInTz(hour: number, minute: number, tz: string | null | undefined, from: Date = new Date()): Date {
  const zone = validTz(tz);
  const localNow = new Date(from.getTime() + tzOffsetMs(from, zone));
  for (let d = 0; d < 3; d++) {
    const wall = Date.UTC(localNow.getUTCFullYear(), localNow.getUTCMonth(), localNow.getUTCDate() + d, hour, minute, 0, 0);
    // Two passes resolve the offset at the target instant (it can differ from now's across DST).
    let guess = wall - tzOffsetMs(new Date(wall), zone);
    guess = wall - tzOffsetMs(new Date(guess), zone);
    if (guess > from.getTime()) return new Date(guess);
  }
  return new Date(from.getTime() + 24 * 60 * 60_000);
}

/** hour:minute in `tz` for a UTC instant (for showing an existing schedule). */
export function wallClockInTz(at: Date, tz: string | null | undefined): { hour: number; minute: number } {
  const local = new Date(at.getTime() + tzOffsetMs(at, validTz(tz)));
  return { hour: local.getUTCHours(), minute: local.getUTCMinutes() };
}

