// ---------------------------------------------------------------------------
// The sweep's one read-only SSH round trip, and folding it into the row
// ---------------------------------------------------------------------------

const UNIT_HINTS = ["valheim", "valheim-server"];

/**
 * Read-only probe: container state + the two env vars we care about, guest
 * memory, and the game's log since `sinceSec` (bounded to the last 3000
 * lines). Uses the systemd unit's journal when the unit exists (every server
 * provisioned through wrapDockerGameService), else `docker logs -t`.
 */
export function valheimWatchProbeScript(sinceSec: number): string {
  const since = Math.max(0, Math.floor(sinceSec));
  return [
    `c=valheim`,
    `echo "NXVW:RUN:$(docker inspect -f '{{.State.Running}}' $c 2>/dev/null)"`,
    `echo "NXVW:STARTED:$(docker inspect -f '{{.State.StartedAt}}' $c 2>/dev/null)"`,
    `docker inspect -f '{{range .Config.Env}}{{println .}}{{end}}' $c 2>/dev/null | grep -E '^(CROSSPLAY|RESTART_CRON)=' | sed 's/^/NXVW:ENV:/'`,
    `grep -E '^(MemTotal|MemAvailable):' /proc/meminfo | sed 's/^/NXVW:MEM:/'`,
    `unit=""; for u in ${UNIT_HINTS.join(" ")}; do systemctl cat "$u.service" >/dev/null 2>&1 && { unit="$u.service"; break; }; done`,
    `echo "NXVW:UNIT:\${unit:-none}"`,
    `echo "NXVW:LOG:BEGIN"`,
    `if [ -n "$unit" ]; then journalctl -u "$unit" -o short-unix --no-pager --since @${since} 2>/dev/null | tail -n 3000; ` +
      `else docker logs -t --since ${since} $c 2>&1 | tail -n 3000 | sed -E 's/^([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+Z) /NXVW:DL:\\1 /'; fi`,
    `echo "NXVW:END"`,
  ].join("\n");
}

export type WatchProbe = {
  ok: boolean;
  running: boolean;
  startedAt: Date | null;
  crossplay: boolean;
  /** null = RESTART_CRON not set at all (image default applies). */
  restartCron: string | null;
  mem: { totalMb: number; availMb: number } | null;
  lines: JournalLine[];
};

export function parseWatchProbe(stdout: string): WatchProbe {
  const p: WatchProbe = { ok: /NXVW:END/.test(stdout), running: false, startedAt: null, crossplay: false, restartCron: null, mem: null, lines: [] };
  let memText = "";
  let inLog = false;
  const logRows: string[] = [];
  for (const raw of stdout.split(/\r?\n/)) {
    if (raw.startsWith("NXVW:END")) { inLog = false; continue; }
    if (inLog) {
      const dl = /^NXVW:DL:(\S+) (.*)$/.exec(raw);
      if (dl) {
        const t = Date.parse(dl[1]);
        if (Number.isFinite(t)) logRows.push(`${(t / 1000).toFixed(6)} docker: ${dl[2]}`);
      } else logRows.push(raw);
      continue;
    }
    let m: RegExpExecArray | null;
    if ((m = /^NXVW:RUN:(.*)$/.exec(raw))) p.running = m[1].trim() === "true";
    else if ((m = /^NXVW:STARTED:(.*)$/.exec(raw))) {
      const t = Date.parse(m[1].trim());
      p.startedAt = Number.isFinite(t) && t > 0 ? new Date(t) : null;
    } else if ((m = /^NXVW:ENV:CROSSPLAY=(.*)$/.exec(raw))) p.crossplay = m[1].trim() === "true";
    else if ((m = /^NXVW:ENV:RESTART_CRON=(.*)$/.exec(raw))) p.restartCron = m[1];
    else if ((m = /^NXVW:MEM:(.*)$/.exec(raw))) memText += m[1] + "\n";
    else if (raw.startsWith("NXVW:LOG:BEGIN")) inLog = true;
  }
  p.mem = parseMeminfo(memText);
  p.lines = parseJournalShortUnix(logRows.join("\n"));
  return p;
}

/** The persisted row fields this module reads/writes (Prisma ValheimWatch subset). */
export type WatchRow = CrossplayMemory & {
  state: string;
  stateSince: Date | null;
  logCursor: string | null;
  healQueuedAt: Date | null;
  alertedAt: Date | null;
  healHistory: unknown;
  memLowSince: Date | null;
  memHintSince: Date | null;
};

export type WatchEvaluation = {
  /** Fields to write back (a Prisma update payload, minus bookkeeping the worker adds). */
  data: Record<string, unknown>;
  state: CrossplayState;
  reason: string;
  heal: HealDecision;
  memoryHintStarted: boolean;
  memoryThresholdMb: number | null;
};

/** Where the next probe's log read starts. */
export function nextSinceSec(prev: Pick<WatchRow, "logCursor"> | null, startedAt: Date | null, now: Date): number {
  if (prev?.logCursor) return Math.floor(Number(prev.logCursor));
  // First look: from the container's start (bounded to 24 h back; tail 3000 caps volume).
  const floor = now.getTime() - 24 * 60 * 60_000;
  const from = startedAt ? Math.max(startedAt.getTime() - 5_000, floor) : now.getTime() - 60 * 60_000;
  return Math.floor(from / 1000);
}

function historyDates(v: unknown): Date[] {
  if (!Array.isArray(v)) return [];
  return v.map((s) => new Date(String(s))).filter((d) => Number.isFinite(d.getTime()));
}

/**
 * Fold one probe into the row and decide. Lines at or before the previous
 * cursor are dropped (journalctl --since is inclusive), so a line is never
 * counted twice.
 */
export function evaluateWatch(i: {
  prev: WatchRow | null;
  probe: WatchProbe;
  now: Date;
  jobInFlight: boolean;
  autoHealEnabled: boolean;
}): WatchEvaluation {
  const { prev, probe, now } = i;
  const cursorMs = prev?.logCursor ? Number(prev.logCursor) * 1000 : -Infinity;
  const fresh = probe.lines.filter((l) => l.ts > cursorMs);
  const memPrev: CrossplayMemory = prev ? {
    lastStartAt: prev.lastStartAt, lastShutdownAt: prev.lastShutdownAt, lastActiveAt: prev.lastActiveAt,
    lastRegisteredAt: prev.lastRegisteredAt, lastJoinCodeErrorAt: prev.lastJoinCodeErrorAt, joinCode: prev.joinCode,
    sessionAddr: prev.sessionAddr, players: prev.players, netErrorFirstAt: prev.netErrorFirstAt,
    netErrorLastAt: prev.netErrorLastAt, netErrorCount: prev.netErrorCount,
  } : { ...EMPTY_MEMORY };
  const mem = foldEvents(memPrev, parseValheimEvents(fresh));
  const { state, reason } = classifyCrossplay({ crossplay: probe.crossplay, running: probe.running, mem, now });
  const healMem: HealMemory = { healQueuedAt: prev?.healQueuedAt ?? null, alertedAt: prev?.alertedAt ?? null, healHistory: historyDates(prev?.healHistory) };
  const heal = probe.crossplay
    ? decideHeal({ state, mem, heal: healMem, now, jobInFlight: i.jobInFlight, autoHealEnabled: i.autoHealEnabled })
    : ({ action: "none", why: "crossplay off", clearSpell: !!(healMem.healQueuedAt || healMem.alertedAt) } as HealDecision);

  const lastTs = fresh.length ? fresh[fresh.length - 1].ts : null;
  const data: Record<string, unknown> = {
    checkedAt: now, checkOk: probe.ok, checkError: null,
    crossplay: probe.crossplay, containerRunning: probe.running, restartCron: probe.restartCron,
    state, reason, ...(prev?.state !== state ? { stateSince: now } : {}),
    ...mem,
    ...(lastTs !== null ? { logCursor: (lastTs / 1000).toFixed(6) } : prev?.logCursor ? {} : { logCursor: (now.getTime() / 1000 - 1).toFixed(6) }),
  };
  if (heal.action === "none" && heal.clearSpell) Object.assign(data, { healQueuedAt: null, healJobId: null, alertedAt: null });
  const dayAgo = now.getTime() - 24 * 60 * 60_000;
  const keptHistory = healMem.healHistory.filter((d) => d.getTime() > dayAgo);
  if (heal.action === "restart") {
    Object.assign(data, { healQueuedAt: now, lastHealReason: reason, healHistory: [...keptHistory, now].map((d) => d.toISOString()) });
  } else if (keptHistory.length !== healMem.healHistory.length) {
    data.healHistory = keptHistory.map((d) => d.toISOString());
  }
  if (heal.action === "alert") data.alertedAt = now;

  let memoryHintStarted = false;
  let memoryThresholdMb: number | null = null;
  if (probe.mem) {
    const md = memoryDecision({ ...probe.mem, lowSince: prev?.memLowSince ?? null, hintSince: prev?.memHintSince ?? null, now });
    memoryHintStarted = md.hintStarted;
    memoryThresholdMb = md.thresholdMb;
    Object.assign(data, {
      memTotalMb: probe.mem.totalMb, memAvailMb: probe.mem.availMb, memLowSince: md.lowSince,
      memHintSince: md.hint ? (prev?.memHintSince ?? now) : null,
    });
  }
  return { data, state, reason, heal, memoryHintStarted, memoryThresholdMb };
}
EOF

