import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "../lib/ssh-exec";
import type { SftpServer } from "../lib/sftp";
import {
  valheimWatchProbeScript,
  parseWatchProbe,
  evaluateWatch,
  nextSinceSec,
  type WatchRow,
  type WatchProbe,
  type WatchEvaluation,
} from "../lib/valheim-health";
import { notifyAdmins } from "./monitor";

/**
 * Valheim watch sweep (lib/valheim-health.ts has the rules and the incident).
 *
 * Every minute, for each RUNNING Valheim server: ONE read-only SSH round trip
 * (container state, CROSSPLAY/RESTART_CRON env, /proc/meminfo, the game log
 * since the last processed line), folded into its ValheimWatch row. Crossplay
 * servers are checked every run; non-crossplay ones only every
 * NON_CROSSPLAY_EVERY_MS (memory watch only, there is no crossplay to check).
 *
 * Actions (all audited):
 *   - auto-heal: ONE GAME_POWER restart per broken spell (source "crossplay-heal"),
 *     through the normal job path, never while a job is in flight or players are
 *     connected, at most HEAL_MAX_PER_DAY a day;
 *   - admin alert when still broken after that restart (or the cap/kill switch
 *     stops us restarting), once per spell;
 *   - memory: log once (AuditLog + admin notification) when a sustained
 *     low-memory spell starts; the customer sees a hint. Never restarts for it.
 *
