    await db.valheimWatch.upsert({
      where: { serverId: server.id },
      create: { serverId: server.id, checkedAt: now, checkOk: false, checkError: "probe did not complete" },
      update: { checkedAt: now, checkOk: false, checkError: "probe did not complete" },
