        `Usually fixed by restarting the game; check the Console log for the PlayFab error.`,
      `/admin/servers/${server.id}`
    ).catch((e) => console.error("[valheim-watch] admin alert failed", e));
    await db.auditLog
      .create({ data: { userId: null, action: "gameserver.valheim.crossplay_alert", detail: `${server.hostname}: ${ev.reason} (${ev.heal.why})` } })
      .catch(() => {});
  }

  if (ev.memoryHintStarted) {
    const detail = `${server.hostname}: available memory ${String(ev.data.memAvailMb)} MB of ${String(ev.data.memTotalMb)} MB, under ${ev.memoryThresholdMb} MB for 15+ min`;
    await db.auditLog.create({ data: { userId: null, action: "gameserver.valheim.memory_low", detail } }).catch(() => {});
