"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { MetricsPanel } from "@/components/customer/MetricsPanel";
import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
import { getGamePlayers, getGameLogs } from "@/lib/actions-game-control";
import { fmtBytes } from "@/components/ui/primitives";
import type { GameHeaderData } from "../types";
import { GameJoinLog } from "../GameJoinLog";
import { GameConsoleJoin } from "../GameConsoleJoin";
import { hasPlayerTracking } from "@/lib/game-player-tracking";
import type { ConsoleJoin } from "@/lib/console-join";

/**
 * Overview, on the concept's layout.
 *
 * The version this replaces spent its top third on a "Quick actions" grid of
 * six buttons that only switched tab — including Restart and Stop, which did
 * not power anything and sat one row below the header's real ones — and a
 * "Server overview" table that repeated the game, status and connect string
 * already in the hero directly above it. Then a near-empty "Resource usage"
 * column duplicated the hero's meters a third time.
 *
 * What is here instead is what the concept leads with and the panel did not
 * have anywhere: a live console peek, recent activity, and a player list, with
 * the facts that are NOT in the hero (plan, renewal, created, node) gathered in
 * one place. Everything on this page is real: the charts are Proxmox RRD and
 * ServerDiskSample, the players are RCON, the log tail is journalctl.
 */

type ServerFacts = {
  planName: string;
  planSpec: string;
  createdLabel: string;
  node: string | null;
  serverIdShort: string;
  renewalLabel: string | null;
  autoRenew: boolean;
  /** Granted server: "Free until <date>" / "Renews at $X on <date>" (lib/grant-billing-text.ts). */
  grantRenewalLabel?: string | null;
  grantFree?: boolean;
  variantLabel: string | null;
  /** Effective provisioned disk (plan + any extra), for the disk chart. */
  planTotalGB: number;
};

function Tile({ icon, ink, label, value, sub, bar }: {
  icon: string; ink: string; label: string; value: string; sub?: string; bar?: { pct: number; tone: string };
}) {
  return (
    <div className="flex items-start gap-3.5 rounded-[15px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.62))] px-4 py-3.5">
      <span className="grid h-[38px] w-[38px] flex-none place-items-center rounded-[11px] border border-white/10 bg-white/[0.04]">
        <Icon name={icon} size={17} tone="inherit" className={ink} />
      </span>
      <span className="flex min-w-0 flex-1 flex-col">
        <span className="text-[10.5px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</span>
        <span className="num mt-0.5 truncate text-[19px] font-bold leading-none text-white">{value}</span>
        {bar && (
          <span className="mt-2 h-[5px] w-full overflow-hidden rounded-full bg-white/10">
            <span className="block h-full rounded-full" style={{ width: `${Math.min(100, Math.max(0, bar.pct))}%`, background: bar.tone }} />
          </span>
        )}
        {sub && <span className="mt-1 truncate text-[11.5px] text-tx-faint">{sub}</span>}
      </span>
    </div>
  );
}

function Card({ title, action, children, className = "" }: {
  title: string; action?: React.ReactNode; children: React.ReactNode; className?: string;
}) {
  return (
    <section className={"flex min-w-0 flex-col rounded-[16px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] " + className}>
      <div className="flex items-center gap-3 border-b border-rim-soft px-4 py-3">
        <h3 className="text-[14px] font-extrabold text-white">{title}</h3>
        {action && <span className="ml-auto flex-none">{action}</span>}
      </div>
      <div className="min-w-0 flex-1 p-4">{children}</div>
              <p className="text-[12.5px] text-tx-faint">{data.runtime ? `The game is ${data.runtime.label.toLowerCase()} — nobody can be connected.` : "Server is offline."}</p>
            ) : players && players.length > 0 ? (
              <ul className="flex flex-col gap-1.5">
                {players.slice(0, 8).map((p) => (
                  <li key={p.name} className="flex items-center gap-2.5 rounded-[10px] border border-rim-soft bg-well px-3 py-2">
                    <span className="grid h-[26px] w-[26px] flex-none place-items-center rounded-[8px] bg-[linear-gradient(140deg,#2f6fe0,#7b3fef)] text-[10.5px] font-bold text-white">
                      {p.name.slice(0, 2).toUpperCase()}
                    </span>
                    <span className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-white">{p.name}</span>
                    <span className="flex-none text-[11px] font-semibold text-emerald-400">Online</span>
                  </li>
                ))}
              </ul>
