"use server";

/**
 * Customer panel actions for Valheim servers: the crossplay status card
 * (join code + live badge, from the worker's ValheimWatch row) and the
 * optional "Scheduled restart" setting (a platform GameSchedule in the
 * server's region time, skipped while players are online).
 *
 * Read side never SSHes: it only reads what worker/valheim-watch.ts last saw,
 * so opening the dashboard costs nothing on the guest.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { crossplayBadge, joinInstructions, computeNextRunInTz, type CrossplayBadge } from "./valheim-health";
import { regionTimezone } from "./mod-autoupdate/policy";

export type ValheimStatusView = {
  watched: boolean;
  checkedAt: string | null;
  crossplay: boolean;
  state: string;
  badge: CrossplayBadge;
  badgeLabel: string;
  reason: string | null;
  joinCode: string | null;
  players: number | null;
  joinText: string;
  /** Automatic restart queued for the current broken spell (customer can see we acted). */
  healing: boolean;
  memory: { availMb: number; totalMb: number; hint: boolean } | null;
  schedule: { enabled: boolean; hour: number; minute: number; timezone: string; nextRunAt: string | null };
};

type Result<T = undefined> = ({ ok: true } & (T extends undefined ? object : { data: T })) | { ok: false; error: string };

async function ownedValheim(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true, userId: true, hostname: true,
      node: { select: { region: true } },
      gamePlan: { select: { gameFamily: true } },
      osTemplate: { select: { family: true } },
    },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (fam !== "valheim") throw new Error("Not a Valheim server");
  return { user, server, timezone: regionTimezone(server.node?.region ?? null) };
}

/** The panel-managed schedule: a daily restart that skips when players are online. */
async function panelSchedule(serverId: string) {
  return db.gameSchedule.findFirst({
    where: { serverId, kind: "restart", skipIfPlayers: true, intervalMinutes: null },
    orderBy: { createdAt: "asc" },
  });
}

function safe(err: unknown): string {
  const m = err instanceof Error ? err.message : String(err);
  return m === "Forbidden" || m === "Not found" || m === "Not a Valheim server" ? m : "Something went wrong. Please try again.";
}

export async function getValheimStatus(serverId: string, connect: string | null): Promise<Result<ValheimStatusView>> {
  try {
    const { timezone } = await ownedValheim(serverId);
    const [w, sched] = await Promise.all([
      db.valheimWatch.findUnique({ where: { serverId } }).catch(() => null),
      panelSchedule(serverId),
    ]);
    const b = crossplayBadge(w?.state);
    const joinCode = w?.crossplay ? w.joinCode : null;
    return {
      ok: true,
      data: {
        watched: !!w?.checkedAt,
        checkedAt: w?.checkedAt?.toISOString() ?? null,
        crossplay: !!w?.crossplay,
        state: w?.state ?? "unknown",
        badge: b.badge,
        badgeLabel: b.label,
        reason: w?.reason ?? null,
        joinCode,
        players: w?.players ?? null,
        joinText: joinInstructions({ joinCode: w?.state === "healthy" || w?.state === "reconnecting" ? joinCode : null, connect }),
        healing: !!w?.healQueuedAt && w.state !== "healthy",
        memory: w?.memTotalMb && w.memAvailMb != null ? { availMb: w.memAvailMb, totalMb: w.memTotalMb, hint: !!w.memHintSince } : null,
        schedule: sched
          ? { enabled: sched.enabled, hour: sched.hour, minute: sched.minute, timezone: sched.timezone ?? timezone, nextRunAt: sched.nextRunAt?.toISOString() ?? null }
          : { enabled: false, hour: 5, minute: 0, timezone, nextRunAt: null },
      },
    };
  } catch (err) {
    return { ok: false, error: safe(err) };
  }
}

/**
 * Turn the daily restart on/off or move it. Time is in the server's region
 * zone. One panel-managed schedule per server; other schedules are untouched.
 */
export async function setValheimScheduledRestart(serverId: string, input: { enabled: boolean; hour: number; minute: number }): Promise<Result> {
  try {
    const { user, server, timezone } = await ownedValheim(serverId);
    const hour = Math.trunc(Number(input.hour));
    const minute = Math.trunc(Number(input.minute));
    if (!(hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59)) return { ok: false, error: "Pick a valid time." };
    const existing = await panelSchedule(serverId);
    const nextRunAt = input.enabled ? computeNextRunInTz(hour, minute, timezone) : null;
    if (existing) {
      await db.gameSchedule.update({
        where: { id: existing.id },
        data: { enabled: input.enabled, hour, minute, timezone, nextRunAt, announce: false },
      });
    } else if (input.enabled) {
      const count = await db.gameSchedule.count({ where: { serverId } });
      if (count >= 8) return { ok: false, error: "This server already has the maximum number of schedules." };
      await db.gameSchedule.create({
        data: { serverId, kind: "restart", hour, minute, timezone, skipIfPlayers: true, announce: false, enabled: true, nextRunAt },
      });
    }
    await db.auditLog.create({
      data: {
        userId: user.id,
        action: "gameserver.valheim.scheduled_restart",
        detail: `${server.hostname} ${input.enabled ? `on ${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")} ${timezone}` : "off"}`,
      },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safe(err) };
  }
}

