"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { getValheimStatus, setValheimScheduledRestart, type ValheimStatusView } from "@/lib/actions-valheim-watch";

/**
 * Valheim "Server health" card (Overview tab): the live crossplay badge and
 * join code, the low-memory "restart recommended" hint, and the optional
 * Scheduled restart setting. Everything comes from the worker's ValheimWatch
 * row (worker/valheim-watch.ts) — this never SSHes — and refreshes every 30 s.
 *
 * Colours are portal tokens only (tx / tx-dim / tx-faint / well / rim-hi /
 * mint / amber / rose), which the light theme re-maps, so the card reads the
 * same in both themes.
 */

const BADGE: Record<string, string> = {
  healthy: "border-mint/40 bg-mint/10 text-mint",
  reconnecting: "border-amber/40 bg-amber/10 text-amber",
  attention: "border-rose/40 bg-rose/10 text-rose",
  checking: "border-rim-hi bg-well text-tx-dim",
  off: "border-rim-hi bg-well text-tx-dim",
};
const DOT: Record<string, string> = {
  healthy: "bg-mint",
  reconnecting: "bg-amber animate-pulse",
  attention: "bg-rose",
  checking: "bg-tx-faint",
  off: "bg-tx-faint",
};

function pad(n: number) {
  return String(n).padStart(2, "0");
}

function zoneLabel(tz: string) {
  return tz.replace(/^.*\//, "").replace(/_/g, " ");
}

export function ValheimCrossplayCard({ serverId, connect }: { serverId: string; connect: string | null }) {
  const [v, setV] = useState<ValheimStatusView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [pending, start] = useTransition();
  const [time, setTime] = useState<string | null>(null);
  const [saveMsg, setSaveMsg] = useState<string | null>(null);

  const load = useCallback(() => {
    getValheimStatus(serverId, connect)
      .then((r) => {
        if (r.ok) { setV(r.data); setErr(null); } else setErr(r.error);
      })
      .catch(() => setErr("Could not load the server health."));
  }, [serverId, connect]);

  useEffect(() => {
    load();
    const t = setInterval(load, 30_000);
    return () => clearInterval(t);
  }, [load]);

  if (err && !v) return <p className="text-[12.5px] text-tx-faint">{err}</p>;
  if (!v) return <p className="text-[12.5px] text-tx-faint">Checking…</p>;

  const hhmm = time ?? `${pad(v.schedule.hour)}:${pad(v.schedule.minute)}`;
  const save = (enabled: boolean) => start(async () => {
    setSaveMsg(null);
    const [h, m] = hhmm.split(":").map((x) => Number(x));
    const r = await setValheimScheduledRestart(serverId, { enabled, hour: h, minute: m });
    if (!r.ok) setSaveMsg(r.error);
    else { setSaveMsg(enabled ? "Saved." : "Scheduled restart is off."); setTime(null); load(); }
  });
  const copyCode = () => {
    if (!v.joinCode) return;
    navigator.clipboard?.writeText(v.joinCode).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1600); }, () => {});
  };
  const codeLive = v.state === "healthy" || v.state === "reconnecting";

  return (
    <div className="flex flex-col gap-4">
      {/* Crossplay */}
      <div className="flex flex-col gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className={"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11.5px] font-bold " + (BADGE[v.badge] ?? BADGE.checking)}>
            <span className={"h-1.5 w-1.5 rounded-full " + (DOT[v.badge] ?? DOT.checking)} />
            {v.badgeLabel}
          </span>
          {v.crossplay && v.players != null && codeLive && (
            <span className="text-[11.5px] text-tx-faint">{v.players} player{v.players === 1 ? "" : "s"} on the crossplay session</span>
          )}
        </div>

        {v.crossplay ? (
          <>
            {v.joinCode && (
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-[12px] text-tx-dim">Join code</span>
                <code className={"rounded-[8px] border border-rim-hi bg-well px-2.5 py-1 font-mono text-[14px] font-bold tracking-wider " + (codeLive ? "text-tx" : "text-tx-faint line-through")}>
                  {v.joinCode}
                </code>
                <button type="button" onClick={copyCode} className="rounded-[8px] border border-rim-hi bg-well px-2 py-1 text-[11.5px] font-semibold text-tx-dim transition hover:text-tx">
                  {copied ? "Copied" : "Copy"}
                </button>
              </div>
            )}
            <p className="text-[12.5px] leading-relaxed text-tx-dim">{v.joinText}</p>
            {v.badge === "attention" && (
              <p className="rounded-[10px] border border-rose/35 bg-rose/10 px-3 py-2 text-[12px] leading-relaxed text-tx-body">
                {v.healing
                  ? "Crossplay stopped registering, so we restarted the game automatically. If this stays red after a few minutes, our team has been alerted."
                  : `Crossplay isn't registering right now (${v.reason ?? "no active session"}). We restart it automatically once; our team is alerted if that doesn't fix it.`}
              </p>
            )}
            {v.state === "starting" && <p className="text-[11.5px] text-tx-faint">The server is starting; crossplay usually registers within a minute or two of the world loading.</p>}
            {v.joinCode && !codeLive && v.badge !== "attention" && <p className="text-[11.5px] text-tx-faint">The code changes on every restart. The new one appears here once the server has registered.</p>}
          </>
        ) : (
          <p className="text-[12.5px] leading-relaxed text-tx-dim">
            {v.watched ? "Crossplay is off. " : ""}Players join by IP{connect ? ` ${connect}` : ""}. Turn Crossplay on in Settings to let Xbox / PlayStation / Game Pass players join with a code.
          </p>
        )}
      </div>

      {/* Memory hint */}
      {v.memory?.hint && (
        <p className="rounded-[10px] border border-amber/35 bg-amber/10 px-3 py-2 text-[12px] leading-relaxed text-tx-body">
          <b className="text-amber">Restart recommended.</b> Your server has been low on free memory for a while ({v.memory.availMb} MB free of {v.memory.totalMb} MB).
          A restart when nobody is playing frees it; if it keeps happening, a larger plan or fewer mods will help.
        </p>
      )}

      {/* Scheduled restart */}
      <div className="flex flex-col gap-2 border-t border-rim-soft pt-3">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-[12.5px] font-bold text-tx">Scheduled restart</span>
          <span className={"rounded-full border px-2 py-0.5 text-[10.5px] font-bold " + (v.schedule.enabled ? "border-mint/40 bg-mint/10 text-mint" : "border-rim-hi bg-well text-tx-faint")}>
            {v.schedule.enabled ? "On" : "Off"}
          </span>
        </div>
        <p className="text-[11.5px] leading-relaxed text-tx-faint">
          Optional. Restarts the game once a day at the time you pick ({zoneLabel(v.schedule.timezone)} time, your server&apos;s region). Skipped on any day players are online at that moment.
        </p>
        <div className="flex flex-wrap items-center gap-2">
          <input
            type="time"
            value={hhmm}
            onChange={(e) => setTime(e.target.value)}
            className="rounded-[9px] border border-rim-hi bg-well px-2.5 py-1.5 text-[12.5px] text-tx [color-scheme:light_dark]"
            aria-label={`Restart time (${v.schedule.timezone})`}
          />
          <button type="button" disabled={pending} onClick={() => save(true)}
            className="rounded-[9px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx transition hover:border-brand-400/45 disabled:opacity-40">
            {v.schedule.enabled ? "Update time" : "Turn on"}
          </button>
          {v.schedule.enabled && (
            <button type="button" disabled={pending} onClick={() => save(false)}
              className="rounded-[9px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-tx disabled:opacity-40">
              Turn off
            </button>
          )}
          {saveMsg && <span className="text-[11.5px] text-tx-faint">{saveMsg}</span>}
        </div>
        {v.schedule.enabled && v.schedule.nextRunAt && (
          <p className="text-[11.5px] text-tx-faint">
            Next: {new Date(v.schedule.nextRunAt).toLocaleString(undefined, { timeZone: v.schedule.timezone, weekday: "short", hour: "2-digit", minute: "2-digit" })} ({zoneLabel(v.schedule.timezone)})
          </p>
        )}
      </div>
    </div>
  );
}

