  add("identity", "FAIL", `SSH failed: ${String((e as Error)?.message ?? e).slice(0, 200)}`);
}

if (planMb) {
  const okGuest = guestMemMb !== null && guestMemMb >= planMb * 0.9;
  const okCfg = cfgMem === planMb;
  const okBalloon = cfgBalloon === null || cfgBalloon === 0 || cfgBalloon >= planMb;
  add("memory", okGuest && okCfg && okBalloon ? "PASS" : okGuest && okCfg ? "WARN" : "FAIL",
    `plan ${planMb} MB; Proxmox memory ${Number.isFinite(cfgMem) ? cfgMem : "?"} MB, balloon ${cfgBalloon ?? "unset"}; guest sees ${guestMemMb ?? "?"} MB`);
}

// ---- Ports: in-guest binding + external reachability
if (fam && !checks.some((c) => c.name === "identity" && c.verdict === "FAIL")) {
  const publicHost = server.dedicatedIp?.address ?? node.publicIp;
  for (const jp of joinPortsFor(fam)) {
    const bound = await gamePortBoundInGuest(server as any, jp.port, jp.protocol);
    // Valheim's server binds the game port (2456) and the query port (2457) only; 2458 is forwarded because Valve
    // asks for the 3-port block, but the process never listens on it (verified on a healthy server, 2026-10-02).
    const reservedOnly = fam === "valheim" && jp.port === 2458 && bound === false;
    add(`ports-guest ${jp.port}/${jp.protocol}`, bound === true || reservedOnly ? "PASS" : bound === false ? "FAIL" : "WARN", bound === true ? "bound in the container" : reservedOnly ? "reserved block port: forwarded but not listened on by the game (expected)" : bound === false ? "nothing bound" : "could not read");
    const fwd = server.dedicatedIp ? jp.port : server.portForwards.find((f) => f.guestPort === jp.port && f.protocol === jp.protocol)?.publicPort;
    if (!fwd) {
      add(`ports-public ${jp.port}/${jp.protocol}`, "FAIL", "no public forward for this join port");
      continue;
    }
    if (jp.protocol === "tcp") {
      const r = await checkGamePortOpen(publicHost, fwd, "tcp", { timeoutMs: 10_000, intervalMs: 5_000 });
      add(`ports-public ${jp.port}/tcp`, r.ok ? "PASS" : "FAIL", `${publicHost}:${fwd} ${r.ok ? "accepts connections" : r.error}`);
    } else {
      const info = await queryInfo(publicHost, fwd, 2500).catch(() => null);
      add(`ports-public ${jp.port}/udp`, info ? "PASS" : "WARN",
        info ? `${publicHost}:${fwd} A2S: "${info.name}" ${info.players}/${info.maxPlayers}` : `${publicHost}:${fwd} gave no A2S answer (normal for a non-query port; the in-guest binding above is the evidence)`);
    }
  }
}

const o = overall(checks);
if (asJson) {
  console.log(JSON.stringify({ server: server.hostname, id: server.id, clean: o.clean, checks }, null, 2));
} else {
  console.log(`\n${server.hostname} (${server.id}) — VM ${server.vmid} on ${node.name}\n`);
  for (const c of checks) console.log(`  ${c.verdict.padEnd(4)}  ${c.name.padEnd(24)} ${c.detail}`);

