import test from "node:test";
import assert from "node:assert/strict";
import {
  applyValheimContainerDefaults,
  planValheimRestartCron,
  parseJournalShortUnix,
  parseValheimEvents,
  foldEvents,
  classifyCrossplay,
  decideHeal,
  EMPTY_MEMORY,
  CROSSPLAY_START_WINDOW_MS,
  HEAL_MAX_PER_DAY,
  HEAL_RESTART_GRACE_MS,
  crossplayBadge,
  joinInstructions,
  parseMeminfo,
  memoryDecision,
  MEM_LOW_SUSTAIN_MS,
  computeNextRunInTz,
  wallClockInTz,
  parseWatchProbe,
  evaluateWatch,
  nextSinceSec,
  valheimWatchProbeScript,
  valheimUnitStopFixScript,
  type CrossplayMemory,
  type HealMemory,
} from "../lib/valheim-health";
import { wrapDockerGameService, gameStopTimeoutS } from "../worker/game-variant";

// Literal lines from a real lloesche/valheim-server crossplay guest (throwaway qa-vhheal-yswu, 2026-10-07),
// as `journalctl -u valheim.service -o short-unix` prints them.
const HEALTHY_BOOT = `
1791353720.540056 qa docker[25022]: Oct  7 06:15:20 supervisord: valheim-server INFO - Running Valheim Server
1791353743.732535 qa docker[25022]: Oct  7 06:15:43 supervisord: valheim-server 10/07/2026 06:15:43: Sending PlayFab login request (attempt 1)
1791353754.055365 qa docker[25022]: Oct  7 06:15:54 supervisord: valheim-server 10/07/2026 06:15:54: New session server "NxQA Heal yswu" that has join code , now 0 player(s)
1791353754.055761 qa docker[25022]: Oct  7 06:15:54 supervisord: valheim-server 10/07/2026 06:15:54: Register PlayFab server "NxQA Heal yswu" with IP 178.63.94.114:2456
1791353755.546702 qa docker[25022]: Oct  7 06:15:55 supervisord: valheim-server 10/07/2026 06:15:55: Session "NxQA Heal yswu" registered with join code 807371
1791353758.416915 qa docker[25022]: Oct  7 06:15:58 supervisord: valheim-server 10/07/2026 06:15:58: Session "NxQA Heal yswu" with join code 807371 and IP 178.63.94.114:2456 is active with 0 player(s)
`;
// The TERRAHEIM incident shape (2026-10-07 05:10): registered, then the join-code check throws, never "is active".
const INCIDENT_BOOT = `
1791297001.000000 t docker[1]: Oct  7 05:10:01 supervisord: valheim-server INFO - Running Valheim Server
1791297040.000000 t docker[1]: Oct  7 05:10:40 supervisord: valheim-server 10/07/2026 05:10:40: Sending PlayFab login request (attempt 2)
1791297043.000000 t docker[1]: Oct  7 05:10:43 supervisord: valheim-server 10/07/2026 05:10:43: Session "Nxeon" registered with join code 187714
1791297044.000000 t docker[1]: Oct  7 05:10:44 supervisord: valheim-server   at ZPlayFabMatchmaking.OnCheckJoinCodeSuccess (PlayFab.MultiplayerModels.FindLobbiesResult result) [0x00000] in <abc>:0
`;

const T = (sec: number) => new Date(sec * 1000);

test("container defaults: daily restart disabled + 120 s stop timeout, idempotent, valheim only", () => {
  const catalog = "curl -fsSL https://get.docker.com | sh && docker run -d --name valheim -p 2456-2458:2456-2458/udp -v /opt/valheim/config:/config -e SERVER_NAME='Nxeon' --restart unless-stopped lloesche/valheim-server";
  const out = applyValheimContainerDefaults(catalog, "valheim");
  assert.match(out, /--name valheim -e RESTART_CRON= --stop-timeout 120 -p 2456/);
  assert.equal(applyValheimContainerDefaults(out, "valheim"), out);
  assert.equal(applyValheimContainerDefaults(catalog, "palworld"), catalog);
});

test("wrapped unit: valheim stops with -t 120 and a longer systemd budget; others keep 30 s", () => {
  const script = applyValheimContainerDefaults("docker run -d --name valheim -p 2456-2458:2456-2458/udp lloesche/valheim-server", "valheim");
  const unit = wrapDockerGameService(script, "valheim");
  assert.match(unit, /ExecStop=\/usr\/bin\/docker stop -t 120 valheim/);
  assert.match(unit, /TimeoutStopSec=150/);
  assert.match(unit, /docker create --name valheim .*-e RESTART_CRON= --stop-timeout 120/);
  assert.equal(gameStopTimeoutS("terraria"), 30);
  assert.match(wrapDockerGameService("docker run -d --name terraria -p 7777:7777 ryshe/terraria:latest", "terraria"), /docker stop -t 30 terraria/);
});

test("unit stop fix script patches -t N to -t 120 only for the valheim unit", () => {
  const s = valheimUnitStopFixScript();
  assert.match(s, /stop -t 120 valheim/);
  assert.match(s, /TimeoutStopSec=150/);
  assert.match(s, /daemon-reload/);
});

test("RESTART_CRON plan: unset or a cron -> change; empty -> leave", () => {
  assert.deepEqual(planValheimRestartCron(new Map()), { change: true, current: null });
  assert.deepEqual(planValheimRestartCron(new Map([["RESTART_CRON", "10 5 * * *"]])), { change: true, current: "10 5 * * *" });
  assert.deepEqual(planValheimRestartCron(new Map([["RESTART_CRON", ""]])), { change: false, current: "" });
});

test("parse real healthy boot: start, registered code, active line with IP and players", () => {
  const ev = parseValheimEvents(parseJournalShortUnix(HEALTHY_BOOT));
  assert.deepEqual(ev.map((e) => e.kind), ["start", "players", "registered", "active"]);
  const m = foldEvents(EMPTY_MEMORY, ev);
  assert.equal(m.joinCode, "807371");
  assert.equal(m.sessionAddr, "178.63.94.114:2456");
  assert.equal(m.players, 0);
  const c = classifyCrossplay({ crossplay: true, running: true, mem: m, now: T(1791353800) });
  assert.equal(c.state, "healthy");
});

test("incident: join-code exception after start = broken, immediately", () => {
  const m = foldEvents(EMPTY_MEMORY, parseValheimEvents(parseJournalShortUnix(INCIDENT_BOOT)));
  assert.equal(m.joinCode, "187714");
  assert.equal(classifyCrossplay({ crossplay: true, running: true, mem: m, now: T(1791297050) }).state, "broken");
});

test("no active line: starting inside the window, broken after it", () => {
  const start = parseJournalShortUnix("1791300000.0 x docker[1]: valheim-server INFO - Running Valheim Server");
