test("scheduled restart in region time, DST-safe", () => {
  // Singapore (UTC+8, no DST): 05:00 local = 21:00 UTC the previous day.
  const n = computeNextRunInTz(5, 0, "Asia/Singapore", new Date("2026-10-07T06:00:00Z"));
  assert.equal(n.toISOString(), "2026-10-07T21:00:00.000Z");
  assert.deepEqual(wallClockInTz(n, "Asia/Singapore"), { hour: 5, minute: 0 });
  // Toronto across the 2026-11-01 DST end: 04:30 local is 08:30Z before, 09:30Z after.
  assert.equal(computeNextRunInTz(4, 30, "America/Toronto", new Date("2026-10-31T12:00:00Z")).toISOString(), "2026-11-01T09:30:00.000Z");
  assert.equal(computeNextRunInTz(4, 30, "America/Toronto", new Date("2026-10-30T12:00:00Z")).toISOString(), "2026-10-31T08:30:00.000Z");
  // Strictly after `from`; bad zone falls back to UTC.
  assert.equal(computeNextRunInTz(6, 0, "UTC", new Date("2026-10-07T06:00:00Z")).toISOString(), "2026-10-08T06:00:00.000Z");
  assert.equal(computeNextRunInTz(6, 0, "Not/AZone", new Date("2026-10-07T05:00:00Z")).toISOString(), "2026-10-07T06:00:00.000Z");
});

