    "NXVW:ENV:RESTART_CRON=",
    "NXVW:MEM:MemTotal:        4009984 kB",
    "NXVW:MEM:MemAvailable:    2009984 kB",
    "NXVW:UNIT:valheim.service",
    "NXVW:LOG:BEGIN",
    HEALTHY_BOOT.trim(),
    "NXVW:END",
  ].join("\n");
  const p = parseWatchProbe(out);
  assert.equal(p.ok, true);
  assert.equal(p.crossplay, true);
  assert.equal(p.restartCron, "");
