  assert.match(valheimWatchProbeScript(123), /--since @123/);
});

test("docker-logs fallback lines are normalised to journal form", () => {
  const p = parseWatchProbe("NXVW:RUN:true\nNXVW:LOG:BEGIN\nNXVW:DL:2026-10-07T06:15:58.416915000Z Session \"A\" with join code 111222 and IP 1.2.3.4:2456 is active with 3 player(s)\nNXVW:END");
