/**
 * Valheim self-heal rollout for EXISTING servers (2026-10-07, lib/valheim-health.ts).
 *
 *   npx tsx scripts/valheim-rollout.ts                 # DRY RUN (default): what would change, per server
 *   npx tsx scripts/valheim-rollout.ts --health        # read-only crossplay health report (is it broken right now?)
 *   npx tsx scripts/valheim-rollout.ts --apply         # queue the change, ONLY for servers with 0 players online
 *   ... [--only <serverId>] [--json]
 *
 * What changes: the live container gets RESTART_CRON= (the image's daily 05:10
 * restart is disabled), --stop-timeout 120, and its valheim.service unit's
 * `docker stop -t 30` becomes `-t 120`. Delivered as a normal GAME_CONFIG job
 * (worker/game-config.ts applyValheim), i.e. a container RECREATE: about a
 * minute of downtime, which is why --apply skips any server with players
 * online (or a job already in flight) instead of kicking them. Re-run later to
 * pick up the skipped ones; servers already done show "no change".
 *
 * GAME_CONFIG applies the SAVED settings (Server.gameConfig). Where the saved
 * crossplay / BepInEx choice differs from what is running, the dry run says so,
 * because --apply would bring the container in line with the saved choice too
 * (exactly what a customer pressing Save in Settings would do).
 *
 * Everything except --apply is read-only (one SSH read per server). --apply
 * writes Job + AuditLog rows only; the worker does the rest.
 */
import { db } from "../lib/db";
import type { SftpServer } from "../lib/sftp";
import { evaluateWatch, describeImageRestart, VALHEIM_RESTART_CRON_OFF, type WatchProbe } from "../lib/valheim-health";
import { probeValheim } from "../worker/valheim-watch";
import { playersOnline } from "../worker/game-control";

const args = process.argv.slice(2);
const flag = (f: string) => args.includes(f);
const val = (f: string) => {
  const i = args.indexOf(f);
  return i >= 0 ? args[i + 1] ?? null : null;
};
const APPLY = flag("--apply");
const HEALTH = flag("--health");
const JSON_OUT = flag("--json");
const ONLY = val("--only");

const SELECT = {
  id: true, hostname: true, status: true, userId: true, gameConfig: true, gameVariant: true,
  rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, sshPort: true, guestSshPort: true, ipAddress: true,
  dedicatedIp: { select: { address: true } },
  node: { select: { publicIp: true, name: true } },
  user: { select: { email: true } },
} as const;

type Row = {
  id: string; hostname: string; node: string; owner: string;
  reachable: boolean; error?: string;
  running?: boolean; liveCrossplay?: boolean; savedCrossplay?: boolean; liveBepinex?: boolean | null; savedVariant?: string | null;
  restartCron?: string | null; restartNow?: string; needsChange?: boolean;
  playersLog?: number | null; playersDb?: boolean;
  health?: { state: string; reason: string; joinCode: string | null; lastStartAt: string | null; lastActiveAt: string | null };
  action?: string;
};

function truthy(v: unknown) {
  return v === true || String(v ?? "").toLowerCase() === "true";
}

async function bepinexLive(server: SftpServer): Promise<boolean | null> {
  const { withServerSsh, exec, QUICK_TIMEOUT_MS } = await import("../lib/ssh-exec");
  const r = await withServerSsh(server, (c) => exec(c, `docker inspect -f '{{range .Config.Env}}{{println .}}{{end}}' valheim 2>/dev/null | grep -E '^BEPINEX='`, QUICK_TIMEOUT_MS)).catch(() => null);
  if (!r) return null;
  return /BEPINEX=true/.test(r.stdout);
}

async function main() {
  const servers = await db.server.findMany({
    where: {
      status: "RUNNING",
      ...(ONLY ? { id: ONLY } : {}),
      OR: [{ gamePlan: { gameFamily: "valheim" } }, { osTemplate: { family: "valheim" } }],
    },
    select: SELECT,
    orderBy: { createdAt: "asc" },
  });
  const rows: Row[] = [];
  const now = new Date();
  for (const s of servers) {
    const row: Row = { id: s.id, hostname: s.hostname, node: s.node?.name ?? "?", owner: s.user?.email ?? s.userId, reachable: false };
    rows.push(row);
    let probe: WatchProbe;
    try {
      // No cursor: read from the container's own start so the latest boot is in view.
      probe = await probeValheim(s as unknown as SftpServer, null, now);
    } catch (e) {
      row.error = String((e as Error)?.message ?? e).slice(0, 160);
      continue;
    }
    if (!probe.ok) { row.error = "probe did not complete"; continue; }
    row.reachable = true;
    row.running = probe.running;
    row.liveCrossplay = probe.crossplay;
    row.savedCrossplay = truthy((s.gameConfig as Record<string, unknown> | null)?.CROSSPLAY);
    row.savedVariant = s.gameVariant;
    row.restartCron = probe.restartCron;
    row.restartNow = describeImageRestart(probe.restartCron);
    row.needsChange = probe.restartCron !== VALHEIM_RESTART_CRON_OFF;
    const ev = evaluateWatch({ prev: null, probe, now, jobInFlight: false, autoHealEnabled: false });
    row.playersLog = (ev.data.players as number | null | undefined) ?? null;
    row.playersDb = await playersOnline(s.id);
    if (!HEALTH) row.liveBepinex = await bepinexLive(s as unknown as SftpServer);
    if (HEALTH || probe.crossplay) {
      row.health = {
        state: ev.state, reason: ev.reason, joinCode: (ev.data.joinCode as string | null) ?? null,
        lastStartAt: (ev.data.lastStartAt as Date | null)?.toISOString() ?? null,
        lastActiveAt: (ev.data.lastActiveAt as Date | null)?.toISOString() ?? null,
      };
    }

    if (HEALTH) continue;
    if (!row.needsChange) { row.action = "no change (daily restart already off)"; continue; }
    const busyPlayers = (row.playersLog ?? 0) > 0 || row.playersDb;
    const inflight = await db.job.count({ where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } } });
    if (busyPlayers) { row.action = "SKIP: players online (re-run later)"; continue; }
    if (inflight > 0) { row.action = "SKIP: a job is already in flight"; continue; }
    if (!probe.running) { row.action = "SKIP: game not running (applies on its next settings save / re-run)"; continue; }
    if (!APPLY) { row.action = "WOULD QUEUE GAME_CONFIG (container recreate, ~1 min downtime)"; continue; }
    const job = await db.$transaction(async (tx) => {
      const busy = await tx.job.count({ where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } } });
      if (busy > 0) return null;
      const j = await tx.job.create({ data: { type: "GAME_CONFIG", serverId: s.id, payload: { source: "valheim-rollout" } } });
      await tx.auditLog.create({ data: { userId: null, action: "gameserver.valheim.rollout_daily_restart_off", detail: `${s.hostname} job=${j.id} restartCron=${JSON.stringify(probe.restartCron)}` } });
      return j;
    });
    row.action = job ? `QUEUED GAME_CONFIG ${job.id}` : "SKIP: a job appeared in flight";
  }

  if (JSON_OUT) {
    console.log(JSON.stringify({ mode: HEALTH ? "health" : APPLY ? "apply" : "dry-run", at: now.toISOString(), servers: rows }, null, 2));
  } else {
    console.log(`\nValheim rollout — ${HEALTH ? "HEALTH REPORT (read-only)" : APPLY ? "APPLY" : "DRY RUN (nothing queued; pass --apply)"} — ${now.toISOString()}\n`);
    for (const r of rows) {
      console.log(`${r.hostname} (${r.id}) on ${r.node} — ${r.owner}`);
      if (!r.reachable) { console.log(`   UNREACHABLE: ${r.error}`); continue; }
      console.log(`   game running: ${r.running}; crossplay live=${r.liveCrossplay} saved=${r.savedCrossplay}${r.liveCrossplay !== r.savedCrossplay ? "  <-- DIFFERS: GAME_CONFIG would apply the saved value" : ""}`);
      if (!HEALTH) {
        const wantB = r.savedVariant === "bepinex";
        console.log(`   variant saved=${r.savedVariant ?? "vanilla"} BepInEx live=${r.liveBepinex}${r.liveBepinex !== null && r.liveBepinex !== wantB ? "  <-- DIFFERS: GAME_CONFIG would apply the saved variant" : ""}`);
        console.log(`   image restart schedule: ${r.restartNow}${r.needsChange ? "  -> will become: off" : ""}`);
      }
      console.log(`   players: log=${r.playersLog ?? "?"} tracked-online=${r.playersDb}`);
      if (r.health) console.log(`   crossplay health: ${r.health.state.toUpperCase()} — ${r.health.reason} code=${r.health.joinCode ?? "-"} lastStart=${r.health.lastStartAt ?? "-"} lastActive=${r.health.lastActiveAt ?? "-"}`);
      if (r.action) console.log(`   => ${r.action}`);
    }
    const broken = rows.filter((r) => r.health?.state === "broken");
    console.log(`\n${rows.length} Valheim server(s); ${rows.filter((r) => r.liveCrossplay).length} with crossplay live; ${broken.length} crossplay BROKEN right now${broken.length ? `: ${broken.map((r) => r.hostname).join(", ")}` : ""}.`);
  }
  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

