type WatchServer = SftpServer & {
  id: string;
  userId: string;
  hostname: string;
  node: { publicIp: string; name: string } | null;
  valheimWatch: (WatchRow & { id: string; checkedAt: Date | null; crossplay: boolean }) | null;
};

/** Read-only probe of one server. Exported for the rollout/health report script. */
export async function probeValheim(server: SftpServer, prev: Pick<WatchRow, "logCursor"> | null, now: Date, startedAtHint?: Date | null): Promise<WatchProbe> {
  const since = nextSinceSec(prev, startedAtHint ?? null, now);
  // When there is no cursor yet, read from the container's own start: ask for it first.
  let script = valheimWatchProbeScript(since);
  if (!prev?.logCursor && startedAtHint === undefined) {
    const first = await withServerSsh(server, (conn) => exec(conn, `docker inspect -f '{{.State.StartedAt}}' valheim 2>/dev/null`, QUICK_TIMEOUT_MS));
    const t = Date.parse(first.stdout.trim());
    script = valheimWatchProbeScript(nextSinceSec(null, Number.isFinite(t) && t > 0 ? new Date(t) : null, now));
  }
  const r = await withServerSsh(server, (conn) => exec(conn, script, QUICK_TIMEOUT_MS * 2));
  return parseWatchProbe(r.stdout);
}

async function checkOne(server: WatchServer, now: Date): Promise<WatchEvaluation | null> {
  const prev = server.valheimWatch;
  let probe: WatchProbe;
  try {
    probe = await probeValheim(server, prev, now);
  } catch (e) {
    const msg = String((e as Error)?.message ?? e).slice(0, 300);
    await db.valheimWatch.upsert({
      where: { serverId: server.id },
      create: { serverId: server.id, checkedAt: now, checkOk: false, checkError: msg },

